#!/usr/bin/env python3
"""Scientific figures for native limiting bulk characteristics and source precision."""
from pathlib import Path
import argparse,json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=argparse.ArgumentParser();p.add_argument('evidence_root',type=Path);a=p.parse_args();E=a.evidence_root;P=E/'native-scri-symbol-v1';Q=E/'native-trace-chart-v1';j=json.loads((P/'summary.json').read_text());normal=[r for r in j['records']if r['boundary_normal']];fig,ax=plt.subplots(figsize=(8,4),constrained_layout=True);x=np.arange(len(normal));ax.plot(x,[r['raw_normal_low']for r in normal],'o',label='Native20 tangent branch (10 modes)');ax.plot(x,[r['raw_normal_high']for r in normal],'o',label='Native20 outgoing branch (10 modes)');ax.plot(x,[r['raw22_algebraic_speed']for r in normal],'x',label='Raw algebraic Jordan block (2 modes)');ax.axhline(0,color='black',linewidth=.6);ax.set_xlabel('Existing endpoint state index (synthetic / full clock / linear TT)');ax.set_ylabel('Signed outward-normal coordinate speed');ax.set_ylim(-.15,5.6);ax.set_title('Actual limiting bulk symbol: no incoming physical normal branch\nBoundary DAE / numerical closure remains open',fontsize=11);ax.grid(alpha=.2);ax.legend(fontsize=8);fig.savefig(P/'native-scri-bulk-characteristics.png',dpi=180);plt.close(fig)
endpoint_rows=[json.loads(s)for s in(Q/'native.jsonl').read_text().splitlines()];endpoint_error=max(r['oracle22_scaled']for r in endpoint_rows if r['mode']in[1,3]);j=json.loads((Q/'approach-review.json').read_text());r=j['records'];omega=np.array([v['omega']for v in r]);err=np.array([v['raw_oracle22_scaled_error']for v in r]);coefficient=np.median(err*omega**2);xx=np.geomspace(omega.min()/2,omega.max()*2,100);fig,ax=plt.subplots(figsize=(7,4),constrained_layout=True);ax.loglog(omega,err,'o',label='Unchanged finite native trace-source error');ax.loglog(xx,coefficient/xx**2,'--',label='Observed coefficient / Omega² (conditioning guide)');ax.axhline(1e-10,color='black',linestyle=':',label='Original raw point budget');ax.set_xlabel('Positive Omega');ax.set_ylabel('Maximum scaled source/oracle defect');ax.set_title('Both deep finite-point criteria fail; exact-face quotient is separate',fontsize=11);ax.text(.02,.65,f'Exact-face analytic controls: <= {endpoint_error:.2e}\nNo floor, no gauge change, no numerical adoption',transform=ax.transAxes,fontsize=9,bbox={'facecolor':'white','edgecolor':'none','alpha':.85});ax.grid(alpha=.2);ax.legend(fontsize=8);fig.savefig(Q/'native-trace-source-conditioning.png',dpi=180);plt.close(fig)
